    "Vareliox closed before finishing. You can continue without losing the chat.": "Vareliox wurde vor dem Abschluss geschlossen. Sie können fortsetzen, ohne den Chat zu verlieren.",
    "Vareliox closed or lost the connection before completing this response.": "Vareliox hat die Verbindung vor dem Abschließen dieser Antwort geschlossen oder verloren.",
    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Vareliox scanniert das gesamte Laufwerk nicht automatisch. Es verwendet nur Pfade, die mit Ihrer Anfrage verbunden sind und ändert niemals externe Ordner ohne Sie zu informieren.",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Vareliox kennt nie dein Passwort. Linux fordert Autorisierung durch das System an; Windows zeigt UAC. Administratorbefehle werden nie automatisch ausgeführt.",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Vareliox kennt nie dein Passwort. Bei Linux fragt sudo nach Systemautorisierung; bei Windows erscheint UAC. Admin-Befehle werden nie automatisch ausgeführt.",
