    "Vareliox will use the level and shell selected in Settings > Terminal. Review the command before approving it.": "Vareliox wird das ausgewählte Level und Shell in den Einstellungen > Terminal verwenden. Überprüfen Sie den Befehl vor der Genehmigung.",
