    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Vareliox non esegue lo scan del disco automaticamente. Utilizza solo percorsi correlati alla tua richiesta e non mai modifica una cartella esterna senza mostrarti l'operazione.",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Vareliox non conosce mai la tua password. Linux richiede l'autorizzazione tramite il sistema; Windows mostra UAC. I comandi amministrativi non vengono mai eseguiti automaticamente.",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Vareliox non conosce mai la tua password. Su Linux, sudo richiede l'autorizzazione del sistema; su Windows, appare UAC. I comandi di amministratore non vengono mai eseguiti automaticamente.",
