    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Nova不会自动扫描整个磁盘。它只会使用与您的请求相关的路径，并且永远不会在没有向您显示操作的情况下更改外部文件夹。",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Nova从不知道你的密码。Linux通过系统请求授权；Windows显示UAC。管理员命令从不自动运行。",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Nova从不知道你的密码。在Linux上，sudo会要求系统授权；在Windows上，UAC会出现。管理员命令从不自动运行。",
