    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Novaは自動的に全ディスクをスキャンしません。リクエストに関連するパスのみを使用し、外部フォルダを変更する際には常に操作を表示します。",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Novaはあなたのパスワードを知りません。Linuxはシステムを通じて認証を求める；WindowsはUACを表示します。管理者コマンドは決して自動的に実行されません。",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Novaはあなたのパスワードを知りません。Linuxではsudoがシステム認証を求め、WindowsではUACが表示されます。管理者コマンドは決して自動的に実行されません。",
