    "Vareliox adapts commands to the operating system.": "Nova는 운영 체제에 따라 명령어를 적응합니다.",
    "Vareliox cannot run any commands.": "Nova는 어떠한 명령어도 실행할 수 없습니다.",
    "Vareliox closed before finishing. You can continue without losing the chat.": "Nova가 완료되기 전에 닫혔습니다. 대화를 잃지 않고 계속할 수 있습니다.",
    "Vareliox closed or lost the connection before completing this response.": "Nova가 이 응답을 완료하기 전에 연결이 종료되었거나 손실되었습니다.",
    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Nova는 자동으로 전체 디스크를 스캔하지 않습니다. 요청에 관련된 경로만 사용하며, 외부 폴더를 변경할 때마다 알려드립니다.",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Nova는 비밀번호를 알 수 없습니다. Linux는 시스템을 통해 권한을 요청하며, Windows는 UAC을 표시합니다. 관리자 명령어는 절대로 자동으로 실행되지 않습니다.",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Nova는 당신의 비밀번호를 알 수 없습니다. Linux에서는 sudo가 시스템 권한을 요청하고, Windows에서는 UAC이 나타납니다. 관리자 명령어는 절대 자동으로 실행되지 않습니다.",
    "Vareliox will create a local recovery copy first.": "Nova는 먼저 로컬 복구 사본을 생성합니다.",
    "Vareliox will create one before changing files.": "Nova는 파일 변경 전에 복구본을 만듭니다.",
    "Vareliox will use the level and shell selected in Settings > Terminal. Review the command before approving it.": "Nova는 설정 > 터미널에서 선택한 레벨과 셸을 사용합니다. 명령을 승인하기 전에 확인하세요.",
    "Vareliox Chat does not receive automatic project access.": "Vareliox Chat는 자동 프로젝트 접근을 받지 않습니다.",
    "Vareliox Chat does not store models.": "Vareliox Chat는 모델을 저장하지 않습니다.",
    "NVIDIA is animating your image…": "NVIDIA가 이미지를 애니메이션하고 있습니다...",
