    "NVIDIA limits the initial image size.": "NVIDIA는 초기 이미지 크기를 제한합니다.",
    "Official ComfyUI guide": "공식 ComfyUI 가이드",
    "Ollama and LM Studio manage chat and vision. Image and video creation requires ComfyUI.": "Ollama와 LM Studio는 챗과 비전을 관리합니다. 이미지와 비디오 생성에는 ComfyUI가 필요합니다.",
    "Ollama, LM Studio, or an API": "올라마, LM 스토리지 또는 API",
    "On Linux, select the folder and press “Open” in the picker. If that button does not appear, copy the path and paste it above.": "Linux에서 폴더를 선택하고 선택기를 클릭하여 \"열기\"를 누릅니다. 해당 버튼이 나타나지 않으면 경로를 복사하고 위에 붙여넣습니다.",
