    "Vareliox adapts commands to the operating system.": "Vareliox адаптирует команды к операционной системе.",
    "Vareliox cannot run any commands.": "Vareliox не может выполнять никаких команд.",
    "Vareliox closed before finishing. You can continue without losing the chat.": "Vareliox закрылась до завершения. Вы можете продолжить без потери чата.",
    "Vareliox closed or lost the connection before completing this response.": "Vareliox закрыла или потеряла соединение до завершения этого ответа.",
    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Vareliox не сканирует весь диск автоматически. Он использует только пути, связанные с вашим запросом, и никогда не изменяет внешнюю папку без вашего разрешения.",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Vareliox никогда не знает ваш пароль. Linux запрашивает авторизацию через систему; Windows показывает UAC. Команды администратора никогда не выполняются автоматически.",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Vareliox никогда не знает ваш пароль. На Linux sudo запрашивает системную авторизацию; на Windows появляется UAC. Команды администратора никогда не выполняются автоматически.",
    "Vareliox will create a local recovery copy first.": "Сначала Vareliox создаст локальную резервную копию.",
    "Vareliox will create one before changing files.": "Vareliox создаст точку перед изменением файлов.",
    "Vareliox will use the level and shell selected in Settings > Terminal. Review the command before approving it.": "Vareliox будет использовать уровень и оболочку, выбранные в Настройках > Терминал. Проверьте команду перед ее одобрением.",
