    "Vareliox closed before finishing. You can continue without losing the chat.": "تم إغلاق نووا قبل الانتهاء. يمكنك المواصلة دون فقدان الدردشة.",
    "Vareliox closed or lost the connection before completing this response.": "تم إغلاق أو فقدان اتصال نووا قبل الانتهاء من هذا الإجابة.",
    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "يقوم نووا بمسح القرص بالطريقة التلقائية. إنه يستخدم فقط المسارات ذات الصلة بطلبك ولا يغير أي مجلد خارجي بدون إظهارك العملية.",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Vareliox لا تعرف كلمة المرور الخاصة بك. يطلب Linux التأكيد من النظام; يظهر Windows UAC. لا تُنفذ الأوامر المدارة تلقائيًا.",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Vareliox لا تعرف كلمة المرور الخاصة بك. في Linux، يطلب sudo إذن النظام; في Windows، يظهر UAC. لا تُنفذ الأوامر بالصلاحيات المطلوبة تلقائيًا.",
    "Vareliox will create a local recovery copy first.": "سوف ينشئ نووا نسخة استعادة محلية أولاً.",
    "Vareliox will create one before changing files.": "سينشئ Vareliox نسخة قبل تغيير الملفات.",
    "Vareliox will use the level and shell selected in Settings > Terminal. Review the command before approving it.": "ستستخدم Vareliox مستوى وشل المختار في الإعدادات > التERMINAL. تحقق من الأمر قبل الموافقة عليه.",
