    "Vareliox adapts commands to the operating system.": "Vareliox ऑपरेटिंग सिस्टम के लिए कमांडों को परिवर्तित करता है।",
    "Vareliox cannot run any commands.": "Vareliox को कोई कमांड नहीं चल सकता।",
    "Vareliox closed before finishing. You can continue without losing the chat.": "न्यूआवा अंत से पहले बंद हुई। चैट को खोजने के लिए जानकारी नहीं होगी।",
    "Vareliox closed or lost the connection before completing this response.": "Vareliox इस प्रतिक्रिया को पूरा करने से पहले बंद हुई या कoneksi खोयी।",
    "Vareliox does not scan the whole disk automatically. It only uses paths related to your request and can never change an external folder without showing you the operation.": "Vareliox पूरी डिस्क को अपने आप स्कैन नहीं करता। यह केवल आपके अनुरोध से जुड़े पथों का उपयोग करता है और कार्रवाई दिखाए बिना किसी बाहरी फ़ोल्डर को नहीं बदल सकता।",
    "Vareliox never knows your password. Linux requests authorization through the system; Windows shows UAC. Administrator commands never run automatically.": "Vareliox आपका पासवर्ड जानता नहीं। Linux अपराध को प्रणाली से अनुमति देता है; Windows UAC दिखाता है। अधिकारी कमांड नहीं अंतोंसे चलते।",
    "Vareliox never knows your password. On Linux, sudo asks for system authorization; on Windows, UAC appears. Administrator commands never run automatically.": "Vareliox आपका पासवर्ड जानता नहीं। लिनक्स पर, sudo तुम्हारे प्रणाली की अनुमति की जाँच करता है; विंडोज पर, UAC दिखता है। प्रशासकीय कमांडें नever आपने नहीं चलती हैं।",
    "Vareliox will create a local recovery copy first.": "नोवा नंतर स्थानीय प्रतिवटन कопी बनाएगा।",
    "Vareliox will create one before changing files.": "Vareliox फ़ाइलें बदलने से पहले एक प्रति बनाएगा।",
    "Vareliox will use the level and shell selected in Settings > Terminal. Review the command before approving it.": "Vareliox will use the level and shell selected in Settings > Terminal. Review the command before approving it.",
    "Vareliox Chat does not receive automatic project access.": "Vareliox Chat नहीं प्रोजेक्ट के लिए आटोमॅटिक अनुमति प्राप्त करता है।",
    "Vareliox Chat does not store models.": "नोवाएआई मॉडलों को संग्रहीत नहीं करता है।",
    "NVIDIA is animating your image…": "NVIDIA आपका छवि चढ़ा रहा है...",
    "NVIDIA is creating your image…": "नाइवीडीवी आपका चित्र बनाए रहा है...",
    "NVIDIA limits the initial image size.": "नाइवीडीवी अर्थात् नाइवीडीवी अपने प्रारम्भिक छवि आकार को सीमित करता है।",
    "Official ComfyUI guide": "आधिकारिक ComfyUI गाइड",
    "Ollama and LM Studio manage chat and vision. Image and video creation requires ComfyUI.": "Ollama और LM Studio चैट और दृश्यता का प्रबंधन करते हैं। चित्र और वीडियो बनाने के लिए ComfyUI की आवश्यकता है।",
    "Ollama, LM Studio, or an API": "Ollama, LM Studio, या API",
    "On Linux, select the folder and press “Open” in the picker. If that button does not appear, copy the path and paste it above.": "Linux पर, फोल्डर का चयन करें और चुनावकार में \"Open\" बटन पर क्लिक करें। यदि यह बटन दिखता नहीं है, तो पथ को कॉपी करें और इसे ऊपर पेस करें।",
